  try {
    checkRequestSource(request, manifest, options.admission);
    const validation = validateManifest(manifest);
    if (validation.issues.length)
      throw Error(
        `REVIEW_MANIFEST:${validation.issues.map((x) => x.code).join(",")}`,
      );
