    await writeFile(path, contents);
    raw[key] = {
      path,
      bytes: Buffer.byteLength(contents),
      sha256: hash(contents),
    };
  }
  const copiedFiles = [
    ["output/events.jsonl", "{}\n"],
    ["output/result.md", report],
    ["output/stderr.txt", ""],
    ["output/record.json", '{"exitCode":0}'],
  ];
  const artifacts = [],
    exclusions = [];
  for (const [path, contents] of copiedFiles) {
    await writeFile(join(copied, path), contents);
    artifacts.push({
      path,
      bytes: Buffer.byteLength(contents),
      sha256: hash(contents),
    });
  }
  await writeFile(
    join(run, "shared-raw-index.json"),
    JSON.stringify(artifacts),
  );
  await writeFile(
    join(run, "shared-runtime-exclusions.json"),
