const complete = (status = "PASS") => ({
  events:
    [
      { type: "thread.started", thread_id: "fixture-thread" },
      { type: "turn.started" },
      {
        type: "item.completed",
        item: {
          id: "fixture-message",
          type: "agent_message",
          text: `GATE_STATUS: ${status}`,
        },
      },
      { type: "turn.completed" },
    ]
      .map((e) => JSON.stringify(e))
      .join("\n") + "\n",
  report: `GATE_STATUS: ${status}\n`,
  stderr: "",
  exit: 0,
  canary: "PASS",
  runtime:
    "/mnt/c/Users/NVISEN/.codex/review-automation/packet-v1-20261001T061101Z/linux-runtime",
  version: "0.159.3",
});
