    "--exec",
    "/usr/bin/pgrep",
    "-af",
    "--",
    binding.runId,
  ];
  let raw;
  try {
    raw = await (runner ?? executeSharedProbe)(argv);
  } catch (error) {
    raw = {
      pid: null,
      exit: error.code ?? "PROBE_ERROR",
      stdout: error.stdout ?? "",
      stderr: error.stderr ?? "",
      signal: error.signal ?? null,
      killed: error.killed ?? false,
    };
  }
  const probe = { argv, ...raw };
  return sealTermination({
    stopped: stoppedProbe(probe),
